}

struct Options {
  int mode; /* 0 compress, 1 decompress, 2 test */
  int command_set;
  int to_stdout;
  int force;
  int remove_src; /* -1 unset/default keep, 0 keep, 1 rm */
  int squash;
  int copy_stat;
  int quality;
