static int handle_param_short(int argc, char** argv, int* ip, char opt, const char** val) {
  if (*ip + 1 >= argc || argv[*ip+1][0] == '\0') {
    char buf[80]; snprintf(buf, sizeof(buf), "expected parameter for argument -%c", opt); parse_error(buf); return 0;
  }
  *val = argv[++(*ip)]; return 1;
}

static int parse_args(int argc, char** argv, struct Options* o) {
  int endopts = 0;
