      else if (LONG_IS("rm")) { if (eq) { char buf[160]; snprintf(buf,sizeof(buf),"must pass the parameter as --%s=value", name); parse_error(buf); return 0; } if (o->remove_src != -1) { parse_error("argument --rm / -j or --keep / -k already set"); return 0; } o->remove_src = 1; }
      else if (LONG_IS("keep")) { if (eq) { char buf[160]; snprintf(buf,sizeof(buf),"must pass the parameter as --%s=value", name); parse_error(buf); return 0; } if (o->remove_src != -1) { parse_error("argument --rm / -j or --keep / -k already set"); return 0; } o->remove_src = 0; }
      else if (LONG_IS("squash")) { if (eq) { char buf[160]; snprintf(buf,sizeof(buf),"must pass the parameter as --%s=value", name); parse_error(buf); return 0; } if (!set_bool_once(&o->squash, "argument --squash / -s already set")) return 0; }
      else if (LONG_IS("no-copy-stat")) { if (eq) { char buf[160]; snprintf(buf,sizeof(buf),"must pass the parameter as --%s=value", name); parse_error(buf); return 0; } o->copy_stat = 0; }
      else if (LONG_IS("test")) { if (eq) { char buf[160]; snprintf(buf,sizeof(buf),"must pass the parameter as --%s=value", name); parse_error(buf); return 0; } if (!set_command(o,2,"--test")) return 0; }
      else if (LONG_IS("verbose")) { if (eq) { char buf[160]; snprintf(buf,sizeof(buf),"must pass the parameter as --%s=value", name); parse_error(buf); return 0; } if (!set_bool_once(&o->verbose, "argument --verbose / -v already set")) return 0; }
      else if (LONG_IS("concatenated")) { if (eq) { char buf[160]; snprintf(buf,sizeof(buf),"must pass the parameter as --%s=value", name); parse_error(buf); return 0; } if (!set_bool_once(&o->concatenated, "argument --concatenated / -K already set")) return 0; }
      else if (LONG_IS("best")) { if (eq) { char buf[160]; snprintf(buf,sizeof(buf),"must pass the parameter as --%s=value", name); parse_error(buf); return 0; } if (!set_quality(o,"11")) return 0; }
      else if (LONG_IS("quality")) { if (!eq || !*val) { char buf[160]; snprintf(buf,sizeof(buf),"must pass the parameter as --%s=value", name); parse_error(buf); return 0; } if (!set_quality(o,val)) return 0; }
      else if (LONG_IS("lgwin")) { if (!eq || !*val) { char buf[160]; snprintf(buf,sizeof(buf),"must pass the parameter as --%s=value", name); parse_error(buf); return 0; } if (!set_lgwin(o,val)) return 0; }
