      }
#undef LONG_IS
    } else {
      size_t L = strlen(a);
      for (size_t j=1;j<L;j++) {
        char c = a[j]; const char* val = NULL;
        if (c >= '0' && c <= '9') { char tmp[2] = {c,0}; if (!set_quality(o,tmp)) return 0; }
        else if (c == 'c') { if (!set_bool_once(&o->to_stdout, "write to standard output already set")) return 0; }
        else if (c == 'd') { if (!set_command(o,1,"-d")) return 0; }
