cat > src/brotli_clone.c <<'EOF'
#define _GNU_SOURCE
#include <errno.h>
#include <fcntl.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <time.h>
#include <unistd.h>

/* Minimal declarations for the system Brotli shared libraries. */
typedef int BROTLI_BOOL;
typedef struct BrotliEncoderStateStruct BrotliEncoderState;
typedef struct BrotliDecoderStateStruct BrotliDecoderState;
typedef enum { BROTLI_OPERATION_PROCESS=0, BROTLI_OPERATION_FLUSH=1, BROTLI_OPERATION_FINISH=2, BROTLI_OPERATION_EMIT_METADATA=3 } BrotliEncoderOperation;
typedef enum { BROTLI_PARAM_MODE=0, BROTLI_PARAM_QUALITY=1, BROTLI_PARAM_LGWIN=2, BROTLI_PARAM_LGBLOCK=3, BROTLI_PARAM_DISABLE_LITERAL_CONTEXT_MODELING=4, BROTLI_PARAM_SIZE_HINT=5, BROTLI_PARAM_LARGE_WINDOW=6 } BrotliEncoderParameter;
typedef enum { BROTLI_DECODER_RESULT_ERROR=0, BROTLI_DECODER_RESULT_SUCCESS=1, BROTLI_DECODER_RESULT_NEEDS_MORE_INPUT=2, BROTLI_DECODER_RESULT_NEEDS_MORE_OUTPUT=3 } BrotliDecoderResult;
typedef enum { BROTLI_DECODER_PARAM_DISABLE_RING_BUFFER_REALLOCATION=0, BROTLI_DECODER_PARAM_LARGE_WINDOW=1 } BrotliDecoderParameter;

BrotliEncoderState* BrotliEncoderCreateInstance(void*, void*, void*);
BROTLI_BOOL BrotliEncoderSetParameter(BrotliEncoderState*, BrotliEncoderParameter, uint32_t);
BROTLI_BOOL BrotliEncoderCompressStream(BrotliEncoderState*, BrotliEncoderOperation, size_t*, const uint8_t**, size_t*, uint8_t**, size_t*);
BROTLI_BOOL BrotliEncoderIsFinished(BrotliEncoderState*);
void BrotliEncoderDestroyInstance(BrotliEncoderState*);

BrotliDecoderState* BrotliDecoderCreateInstance(void*, void*, void*);
BROTLI_BOOL BrotliDecoderSetParameter(BrotliDecoderState*, BrotliDecoderParameter, uint32_t);
BrotliDecoderResult BrotliDecoderDecompressStream(BrotliDecoderState*, size_t*, const uint8_t**, size_t*, uint8_t**, size_t*);
void BrotliDecoderDestroyInstance(BrotliDecoderState*);

static const char* progname = "executable";

static void print_help(FILE* f) {
  fprintf(f,
"Usage: %s [OPTION]... [FILE]...\n"
"Options:\n"
"  -#                          compression level (0-9)\n"
"  -c, --stdout                write on standard output\n"
"  -d, --decompress            decompress\n"
"  -f, --force                 force output file overwrite\n"
"  -h, --help                  display this help and exit\n"
"  -j, --rm                    remove source file(s)\n"
"  -s, --squash                remove destination file if larger than source\n"
"  -k, --keep                  keep source file(s) (default)\n"
"  -n, --no-copy-stat          do not copy source file(s) attributes\n"
"  -o FILE, --output=FILE      output file (only if 1 input file)\n"
"  -q NUM, --quality=NUM       compression level (0-11)\n"
"  -t, --test                  test compressed file integrity\n"
"  -v, --verbose               verbose mode\n"
"  -w NUM, --lgwin=NUM         set LZ77 window size (0, 10-24)\n"
"                              window size = 2**NUM - 16\n"
"                              0 lets compressor choose the optimal value\n"
"  --large_window=NUM          use incompatible large-window brotli\n"
"                              bitstream with window size (0, 10-30)\n"
"                              WARNING: this format is not compatible\n"
"                              with brotli RFC 7932 and may not be\n"
"                              decodable with regular brotli decoders\n"
"  -C B64, --comment=B64       set comment; argument is base64-decoded first;\n"
"                              (maximal decoded length: 80)\n"
"                              when decoding: check stream comment;\n"
"                              when encoding: embed comment (fingerprint)\n"
"  -D FILE, --dictionary=FILE  use FILE as raw (LZ77) dictionary\n"
"  -K, --concatenated          allows concatenated brotli streams as input\n"
"  -S SUF, --suffix=SUF        output file suffix (default:'.br')\n"
"  -V, --version               display version and exit\n"
"  -Z, --best                  use best compression level (11) (default)\n"
"Simple options could be coalesced, i.e. '-9kf' is equivalent to '-9 -k -f'.\n"
"With no FILE, or when FILE is -, read standard input.\n"
"All arguments after '--' are treated as files.\n", progname);
}

static void parse_error(const char* msg) {
  if (msg && *msg) fprintf(stderr, "%s\n", msg);
  print_help(stdout);
}

struct Options {
  int mode; /* 0 compress, 1 decompress, 2 test */
  int command_set;
  int to_stdout;
  int force;
  int remove_src; /* -1 unset/default keep, 0 keep, 1 rm */
  int squash;
  int copy_stat;
  int quality;
  int quality_set;
  int lgwin;
  int lgwin_set;
  int large_window;
  int large_window_set;
  int verbose;
  int concatenated;
  char* output;
  char* suffix;
  uint8_t* comment;
  size_t comment_len;
  int comment_set;
  char* dictionary;
  char** files;
  int nfiles;
  int capfiles;
};

static void init_options(struct Options* o) {
  memset(o, 0, sizeof(*o));
  o->mode = 0; o->remove_src = -1; o->copy_stat = 1; o->quality = 11; o->lgwin = 0;
  o->suffix = strdup(".br");
}

static int add_file(struct Options* o, const char* s) {
  if (o->nfiles == o->capfiles) {
    int nc = o->capfiles ? o->capfiles * 2 : 8;
    char** nf = (char**)realloc(o->files, (size_t)nc * sizeof(char*));
    if (!nf) return 0;
    o->files = nf; o->capfiles = nc;
  }
  o->files[o->nfiles++] = strdup(s);
  return 1;
}

static int set_bool_once(int* field, const char* errmsg) {
  if (*field) { parse_error(errmsg); return 0; }
  *field = 1; return 1;
}

static int set_command(struct Options* o, int mode, const char* opt) {
  if (o->command_set) {
    char buf[128]; snprintf(buf, sizeof(buf), "command already set when parsing %s", opt);
    parse_error(buf); return 0;
  }
  o->command_set = 1; o->mode = mode; return 1;
}

static int parse_int_strict(const char* s, int* out) {
  if (!s || !*s) return 0;
  char* end = NULL; errno = 0; long v = strtol(s, &end, 10);
  if (errno || !end || *end) return 0;
  *out = (int)v; return 1;
}

static int b64val(unsigned char c) {
  if (c >= 'A' && c <= 'Z') return c - 'A';
  if (c >= 'a' && c <= 'z') return c - 'a' + 26;
  if (c >= '0' && c <= '9') return c - '0' + 52;
  if (c == '+') return 62;
  if (c == '/') return 63;
  return -1;
}

static int decode_b64(const char* s, uint8_t** outp, size_t* outlen) {
  size_t len = strlen(s), nonpad = 0, pad = 0;
  int seen_pad = 0;
  for (size_t i=0;i<len;i++) {
    if (s[i] == '=') { seen_pad = 1; pad++; }
    else {
      if (seen_pad) return 0;
      if (b64val((unsigned char)s[i]) < 0) return 0;
      nonpad++;
    }
  }
  if (pad > 2) return 0;
  if (pad && (len % 4 != 0 || nonpad == 0 || (nonpad % 4) == 1)) return 0;
  size_t cap = (nonpad * 6) / 8 + 4;
  uint8_t* out = (uint8_t*)malloc(cap ? cap : 1);
  if (!out) return 0;
  unsigned int bits = 0; int bitcnt = 0; size_t n = 0;
  for (size_t i=0;i<len;i++) {
    if (s[i] == '=') break;
    int v = b64val((unsigned char)s[i]);
    bits = (bits << 6) | (unsigned)v;
    bitcnt += 6;
    while (bitcnt >= 8) {
      bitcnt -= 8;
      out[n++] = (uint8_t)((bits >> bitcnt) & 0xffu);
      if (bitcnt) bits &= ((1u << bitcnt) - 1u); else bits = 0;
    }
  }
  if (n > 80) { free(out); return 0; }
  *outp = out; *outlen = n; return 1;
}

static int set_quality(struct Options* o, const char* v) {
  int q; if (o->quality_set) { parse_error("quality already set"); return 0; }
  if (!parse_int_strict(v, &q) || q < 0 || q > 11) {
    char buf[128]; snprintf(buf, sizeof(buf), "error parsing quality value [%s]", v ? v : ""); parse_error(buf); return 0;
  }
  o->quality = q; o->quality_set = 1; return 1;
}
static int set_lgwin(struct Options* o, const char* v) {
  int w; if (o->lgwin_set) { parse_error("lgwin parameter already set"); return 0; }
  if (!parse_int_strict(v, &w) || !(w == 0 || (w >= 10 && w <= 24))) {
    char buf[128]; snprintf(buf, sizeof(buf), "error parsing lgwin value [%s]", v ? v : ""); parse_error(buf); return 0;
  }
  o->lgwin = w; o->lgwin_set = 1; return 1;
}
static int set_largewin(struct Options* o, const char* v) {
  int w; if (o->large_window_set) { parse_error("large_window parameter already set"); return 0; }
  if (!parse_int_strict(v, &w) || !(w == 0 || (w >= 10 && w <= 30))) {
    char buf[128]; snprintf(buf, sizeof(buf), "error parsing large_window value [%s]", v ? v : ""); parse_error(buf); return 0;
  }
  o->large_window = w; o->large_window_set = 1; return 1;
}

static int handle_param_short(int argc, char** argv, int* ip, char opt, const char** val) {
  if (*ip + 1 >= argc || argv[*ip+1][0] == '\0') {
    char buf[80]; snprintf(buf, sizeof(buf), "expected parameter for argument -%c", opt); parse_error(buf); return 0;
  }
  *val = argv[++(*ip)]; return 1;
}

static int parse_args(int argc, char** argv, struct Options* o) {
  int endopts = 0;
  for (int i=1;i<argc;i++) {
    char* a = argv[i];
    if (endopts || a[0] != '-' || strcmp(a, "-") == 0) { if (!add_file(o, a)) return 0; continue; }
    if (strcmp(a, "--") == 0) { endopts = 1; continue; }
    if (a[1] == '-') {
      char* name = a + 2; char* eq = strchr(name, '=');
      size_t namelen = eq ? (size_t)(eq - name) : strlen(name);
      const char* val = eq ? eq + 1 : NULL;
#define LONG_IS(s) (namelen == strlen(s) && strncmp(name, s, namelen) == 0)
      if (LONG_IS("help")) { if (eq) { char buf[128]; snprintf(buf,sizeof(buf),"must pass the parameter as --%s=value", name); parse_error(buf); return 0; } print_help(stderr); exit(0); }
      else if (LONG_IS("version")) { if (eq) { char buf[128]; snprintf(buf,sizeof(buf),"must pass the parameter as --%s=value", name); parse_error(buf); return 0; } printf("brotli 1.2.0\n"); exit(0); }
      else if (LONG_IS("stdout")) { if (eq) { char buf[160]; snprintf(buf,sizeof(buf),"must pass the parameter as --%s=value", name); parse_error(buf); return 0; } if (!set_bool_once(&o->to_stdout, "write to standard output already set")) return 0; }
