static int read_all(FILE* f, const char* name, uint8_t** data, size_t* size) {
  size_t cap = 8192, n = 0; uint8_t* buf = (uint8_t*)malloc(cap);
  if (!buf) return 0;
  while (1) {
    if (n == cap) { cap *= 2; uint8_t* nb = (uint8_t*)realloc(buf, cap); if (!nb) { free(buf); return 0; } buf = nb; }
    size_t r = fread(buf+n, 1, cap-n, f); n += r;
    if (r == 0) {
      if (ferror(f)) { fprintf(stderr, "failed to read input [%s]: %s\n", name, strerror(errno)); free(buf); return 0; }
      break;
    }
  }
  *data = buf; *size = n; return 1;
}

struct MemBuf { uint8_t* data; size_t size, cap; };
static int mem_write(struct MemBuf* m, const uint8_t* p, size_t n) {
  if (n == 0) return 1;
  if (m->size + n > m->cap) {
    size_t nc = m->cap ? m->cap * 2 : 1024; while (nc < m->size + n) nc *= 2;
    uint8_t* nd = (uint8_t*)realloc(m->data, nc); if (!nd) return 0; m->data = nd; m->cap = nc;
  }
  memcpy(m->data + m->size, p, n); m->size += n; return 1;
}

static int encode_to_target(const uint8_t* in, size_t insz, int has_size_hint, struct Options* o, FILE* out, struct MemBuf* mem, size_t* outsz, int override_lgwin) {
  BrotliEncoderState* s = BrotliEncoderCreateInstance(NULL,NULL,NULL);
  if (!s) return 0;
  int ok = 1; uint8_t obuf[65536];
  BrotliEncoderSetParameter(s, BROTLI_PARAM_QUALITY, (uint32_t)o->quality);
  int lg = override_lgwin >= 0 ? override_lgwin : (o->large_window_set ? o->large_window : o->lgwin);
  if (o->large_window_set) BrotliEncoderSetParameter(s, BROTLI_PARAM_LARGE_WINDOW, 1);
  BrotliEncoderSetParameter(s, BROTLI_PARAM_LGWIN, (uint32_t)lg);
  if (has_size_hint && insz <= 0xffffffffu) BrotliEncoderSetParameter(s, BROTLI_PARAM_SIZE_HINT, (uint32_t)insz);
  if (o->comment_set && o->comment_len > 0) {
    size_t ai = o->comment_len; const uint8_t* ni = o->comment;
    while (ai > 0) {
      size_t ao = sizeof(obuf); uint8_t* no = obuf;
      if (!BrotliEncoderCompressStream(s, BROTLI_OPERATION_EMIT_METADATA, &ai, &ni, &ao, &no, NULL)) { ok = 0; break; }
      size_t prod = sizeof(obuf) - ao;
      if (prod && out && fwrite(obuf,1,prod,out) != prod) { ok = 0; break; }
      if (prod && mem && !mem_write(mem, obuf, prod)) { ok = 0; break; }
      if (outsz) *outsz += prod;
      if (prod == 0 && ai > 0) { ok = 0; break; }
    }
  }
  size_t ai = insz; const uint8_t* ni = in;
  while (ok && !BrotliEncoderIsFinished(s)) {
    size_t ao = sizeof(obuf); uint8_t* no = obuf;
    if (!BrotliEncoderCompressStream(s, BROTLI_OPERATION_FINISH, &ai, &ni, &ao, &no, NULL)) { ok = 0; break; }
    size_t prod = sizeof(obuf) - ao;
    if (prod && out && fwrite(obuf,1,prod,out) != prod) { ok = 0; break; }
    if (prod && mem && !mem_write(mem, obuf, prod)) { ok = 0; break; }
    if (outsz) *outsz += prod;
  }
  BrotliEncoderDestroyInstance(s);
  return ok;
}

static int make_comment_prefix(const uint8_t* comment, size_t clen, int lgwin, struct MemBuf* pref) {
  struct Options tmp; init_options(&tmp); tmp.comment_set = 1; tmp.comment = (uint8_t*)comment; tmp.comment_len = clen; tmp.lgwin = lgwin; tmp.lgwin_set = 1;
  struct MemBuf m = {0}; size_t os = 0;
  uint8_t dummy = 0;
  if (!encode_to_target(&dummy, 0, 0, &tmp, NULL, &m, &os, lgwin)) { free(m.data); return 0; }
  /* Keep bytes through the literal comment. */
  size_t pos = (size_t)-1;
  for (size_t i=0; i + clen <= m.size; i++) {
    if (clen == 0 || memcmp(m.data+i, comment, clen) == 0) { pos = i; break; }
  }
  if (pos == (size_t)-1) { free(m.data); return 0; }
  size_t plen = pos + clen;
  pref->data = (uint8_t*)malloc(plen ? plen : 1); if (!pref->data) { free(m.data); return 0; }
  memcpy(pref->data, m.data, plen); pref->size = pref->cap = plen;
  free(m.data); free(tmp.suffix); return 1;
}

static int has_comment_prefix(const uint8_t* data, size_t sz, const uint8_t* comment, size_t clen) {
  if (clen == 0) return 1;
  int wins[17]; int n=0; wins[n++]=0; for (int w=10; w<=24; w++) wins[n++]=w;
  for (int i=0;i<n;i++) {
    struct MemBuf p = {0};
    if (make_comment_prefix(comment, clen, wins[i], &p)) {
      int match = (p.size <= sz && memcmp(data, p.data, p.size) == 0);
      free(p.data);
      if (match) return 1;
    }
  }
  return 0;
}

static int decode_to_target(const uint8_t* in, size_t insz, struct Options* o, FILE* out, int discard, size_t* outsz) {
  if (o->comment_set && o->comment_len > 0 && !has_comment_prefix(in, insz, o->comment, o->comment_len)) return 0;
  size_t off = 0; int streams = 0;
  while (1) {
    BrotliDecoderState* s = BrotliDecoderCreateInstance(NULL,NULL,NULL);
    if (!s) return 0;
    BrotliDecoderSetParameter(s, BROTLI_DECODER_PARAM_LARGE_WINDOW, 1);
    const uint8_t* ni = in + off; size_t ai = insz - off; uint8_t obuf[65536];
    int done = 0, ok = 1;
    while (!done) {
      size_t ao = sizeof(obuf); uint8_t* no = obuf;
      BrotliDecoderResult r = BrotliDecoderDecompressStream(s, &ai, &ni, &ao, &no, NULL);
      size_t prod = sizeof(obuf) - ao;
      if (prod && !discard) { if (fwrite(obuf,1,prod,out) != prod) { ok = 0; break; } }
      if (outsz) *outsz += prod;
      if (r == BROTLI_DECODER_RESULT_SUCCESS) { done = 1; break; }
      if (r == BROTLI_DECODER_RESULT_NEEDS_MORE_OUTPUT) continue;
      if (r == BROTLI_DECODER_RESULT_NEEDS_MORE_INPUT) { ok = 0; break; }
      ok = 0; break;
    }
    off = (size_t)(ni - in);
    BrotliDecoderDestroyInstance(s);
    if (!ok || !done) return 0;
    streams++;
    if (!o->concatenated) return off == insz;
    if (off == insz) return 1;
    if (streams > 1000000) return 0;
  }
}

static char* derive_output_name(const char* inname, struct Options* o) {
  if (o->output) return strdup(o->output);
  if (o->mode == 0) {
    size_t a=strlen(inname), b=strlen(o->suffix); char* r=(char*)malloc(a+b+1); memcpy(r,inname,a); memcpy(r+a,o->suffix,b+1); return r;
  } else {
    size_t a=strlen(inname), b=strlen(o->suffix);
    if (a <= b) return strdup("");
    if (strcmp(inname + a - b, o->suffix) != 0) {
      char* r = (char*)malloc(a-b+1); memcpy(r,inname,a-b); r[a-b]=0; return r;
    }
    char* r = (char*)malloc(a-b+1); memcpy(r,inname,a-b); r[a-b]=0; return r;
  }
}

static int open_output_file(const char* path, int force, FILE** fp) {
  int flags = O_WRONLY | O_CREAT | (force ? O_TRUNC : O_EXCL);
  int fd = open(path, flags, 0600);
  if (fd < 0) { fprintf(stderr, "failed to open output file [%s]: %s\n", path, strerror(errno)); return 0; }
  FILE* f = fdopen(fd, "wb"); if (!f) { close(fd); return 0; }
  *fp = f; return 1;
}

static void copy_attrs(const char* out, const struct stat* st) {
  chmod(out, st->st_mode & 07777);
  struct timeval tv[2];
  tv[0].tv_sec = st->st_atime; tv[0].tv_usec = 0;
  tv[1].tv_sec = st->st_mtime; tv[1].tv_usec = 0;
  utimes(out, tv);
}

static double now_sec(void) { struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts); return (double)ts.tv_sec + (double)ts.tv_nsec/1e9; }

static int process_entry(struct Options* o, const char* entry) {
  int is_stdin = (strcmp(entry, "-") == 0);
  const char* display = entry;
  FILE* inf = stdin; struct stat st; memset(&st,0,sizeof(st)); int have_stat = 0;
  if (!is_stdin) {
    inf = fopen(entry, "rb");
    if (!inf) { fprintf(stderr, "failed to open input file [%s]: %s\n", entry, strerror(errno)); return 0; }
    if (stat(entry, &st) == 0) have_stat = 1;
  } else display = "-";
  uint8_t* data = NULL; size_t insz = 0;
  if (!read_all(inf, display, &data, &insz)) { if (!is_stdin) fclose(inf); return 0; }
  if (!is_stdin) fclose(inf);

  int to_stdout = o->to_stdout || is_stdin || o->mode == 2;
  FILE* outf = stdout; char* outname = NULL; int discard = (o->mode == 2); int opened = 0;
  if (!to_stdout && !discard) {
    outname = derive_output_name(entry, o);
    if (!outname || outname[0] == 0) { fprintf(stderr, "empty output file name for %s%s%s input file\n", strchr(entry,'/')?"[":"", entry, strchr(entry,'/')?"]":""); free(data); free(outname); return 0; }
    if (o->mode != 0) {
      size_t a=strlen(entry), b=strlen(o->suffix);
      if (a > b && strcmp(entry+a-b, o->suffix) != 0) { fprintf(stderr, "input file %s suffix mismatch\n", outname); free(data); free(outname); return 0; }
    }
    if (!open_output_file(outname, o->force, &outf)) { free(data); free(outname); return 0; }
    opened = 1;
  }
  double t0 = now_sec(); size_t outsz = 0; int ok;
  if (o->mode == 0) ok = encode_to_target(data, insz, !is_stdin, o, outf, NULL, &outsz, -1);
  else ok = decode_to_target(data, insz, o, outf, discard, &outsz);
  if (opened) {
    if (fclose(outf) != 0) ok = 0;
  } else if (!discard) fflush(outf);
  double dt = now_sec() - t0; if (dt < 0) dt = 0;
  if (!ok) {
    if (opened && outname) unlink(outname);
    fprintf(stderr, "corrupt input [%s]\n", entry);
    free(data); free(outname); return 0;
  }
  if (opened && o->copy_stat && have_stat) copy_attrs(outname, &st);
  if (o->verbose) fprintf(stderr, "%s [%s]: %zu B -> %zu B in %.2f sec\n", o->mode==0?"Compressed":"Decompressed", display, insz, outsz, dt);
  if (opened && o->mode == 0 && o->squash && outsz > insz) {
    unlink(outname);
    if (o->verbose) fprintf(stderr, "Output is larger than input\n");
  } else if (!is_stdin && o->remove_src == 1 && opened) {
    unlink(entry);
  }
  free(data); free(outname); return 1;
}

int main(int argc, char** argv) {
  char* slash = strrchr(argv[0], '/'); progname = slash ? slash + 1 : argv[0];
  struct Options opt; init_options(&opt);
  if (strcmp(progname, "brcat") == 0) { opt.mode = 1; opt.command_set = 1; opt.to_stdout = 1; opt.concatenated = 1; }
  else if (strcmp(progname, "unbrotli") == 0) { opt.mode = 1; opt.command_set = 1; }
  if (!parse_args(argc, argv, &opt)) return 1;
  if (opt.nfiles == 0) add_file(&opt, "-");
  int allok = 1;
  for (int i=0;i<opt.nfiles;i++) {
    if (!process_entry(&opt, opt.files[i])) { allok = 0; break; }
  }
  return allok ? 0 : 1;
}
